import { Glob } from "bun";

const cases: [string, string][] = [
  ["docs/**", "docs/readme.md"],
  ["docs/**", "docs/a/b.md"],
  ["docs/**", "docs"],
  ["docs/**", "src/docs/x.md"],
  ["src/api/**", "src/api/users.ts"],
  ["src/api/**", "src/api/v1/users.ts"],
  ["src/api/**", "src/web/users.ts"],
  ["*.test.*", "foo.test.ts"],
  ["*.test.*", "src/foo.test.ts"],
  ["**/*.test.*", "src/foo.test.ts"],
  ["**/*.test.*", "foo.test.ts"],
  ["*.md", "readme.md"],
  ["*.md", "docs/readme.md"],
];

for (const [pattern, path] of cases) {
  let result: boolean | string;
  try {
    result = new Glob(pattern).match(path);
  } catch (e) {
    result = `THREW: ${(e as Error).message}`;
  }
  console.log(`${pattern.padEnd(14)} vs ${path.padEnd(20)} => ${result}`);
}

