// Unit tests for the PR label assigner core logic.
//
// Written red/green TDD-style: each `describe` block was added as a failing
// test first, then the minimum implementation was written to make it pass.
//
// These are FAST, hermetic tests with no I/O against the live filesystem
// except for tightly-scoped temp files in the config-loading section. They are
// the suite that runs via `bun test`. The end-to-end pipeline (GitHub Actions
// via `act`) is exercised separately by `act-runner.ts`.

import { afterAll, describe, expect, test } from "bun:test";
import { mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import {
  matchPattern,
  assignLabels,
  validateConfig,
  loadConfig,
  loadChangedFiles,
  type LabelerConfig,
} from "../src/labeler.ts";

describe("matchPattern (glob matching)", () => {
  test("matches a recursive directory pattern against nested files", () => {
    expect(matchPattern("docs/**", "docs/readme.md")).toBe(true);
    expect(matchPattern("docs/**", "docs/guide/intro.md")).toBe(true);
  });

  test("does not match files outside the directory pattern", () => {
    expect(matchPattern("docs/**", "src/index.ts")).toBe(false);
    expect(matchPattern("src/api/**", "src/web/app.ts")).toBe(false);
  });

  test("matches a nested api path", () => {
    expect(matchPattern("src/api/**", "src/api/v1/users.ts")).toBe(true);
  });

  test("a basename-style pattern (no slash) matches files in any directory", () => {
    // The task's example rule `*.test.* -> tests` should label a test file
    // wherever it lives, so a slash-free pattern falls back to basename matching.
    expect(matchPattern("*.test.*", "foo.test.ts")).toBe(true);
    expect(matchPattern("*.test.*", "src/components/foo.test.tsx")).toBe(true);
    expect(matchPattern("*.md", "docs/changelog.md")).toBe(true);
  });

  test("a slash-free pattern still rejects non-matching basenames", () => {
    expect(matchPattern("*.test.*", "src/foo.ts")).toBe(false);
    expect(matchPattern("*.md", "src/index.ts")).toBe(false);
  });

  test("a pattern containing a slash is anchored to the full path only", () => {
    // `src/*.ts` must NOT match a deeper file, and must not fall back to basename.
    expect(matchPattern("src/*.ts", "src/index.ts")).toBe(true);
    expect(matchPattern("src/*.ts", "src/api/index.ts")).toBe(false);
    expect(matchPattern("src/*.ts", "index.ts")).toBe(false);
  });

  test("an invalid glob pattern throws a descriptive error", () => {
    // Empty patterns are meaningless and must be rejected loudly.
    expect(() => matchPattern("", "anything")).toThrow(/pattern/i);
  });
});

describe("assignLabels (rule application)", () => {
  const config: LabelerConfig = {
    rules: [
      { label: "documentation", patterns: ["docs/**", "*.md"] },
      { label: "api", patterns: ["src/api/**"], priority: 10 },
      { label: "tests", patterns: ["*.test.*"] },
      { label: "frontend", patterns: ["src/web/**"] },
    ],
  };

  test("assigns a single label when one rule matches", () => {
    const result = assignLabels(["docs/readme.md"], config);
    expect(result.labels).toEqual(["documentation"]);
  });

  test("assigns multiple labels to a PR across different files", () => {
    const result = assignLabels(
      ["docs/readme.md", "src/api/users.ts", "src/web/app.test.tsx"],
      config,
    );
    // Sorted by priority desc, then name asc: api(10), then documentation/frontend/tests(0).
    expect(result.labels).toEqual(["api", "documentation", "frontend", "tests"]);
  });

  test("a single file can receive multiple labels", () => {
    // `src/api/client.test.ts` matches both the api rule and the tests rule.
    const result = assignLabels(["src/api/client.test.ts"], config);
    expect(result.labels).toEqual(["api", "tests"]);
    expect(result.byFile["src/api/client.test.ts"]).toEqual(["api", "tests"]);
  });

  test("labels are de-duplicated across multiple matching files", () => {
    const result = assignLabels(["docs/a.md", "docs/b.md", "README.md"], config);
    expect(result.labels).toEqual(["documentation"]);
  });

  test("orders the final label set by priority (descending) then name", () => {
    const ordered: LabelerConfig = {
      rules: [
        { label: "low", patterns: ["a.txt"], priority: 1 },
        { label: "high", patterns: ["b.txt"], priority: 100 },
        { label: "mid", patterns: ["c.txt"], priority: 50 },
      ],
    };
    const result = assignLabels(["a.txt", "b.txt", "c.txt"], ordered);
    expect(result.labels).toEqual(["high", "mid", "low"]);
  });

  test("returns an empty label set when nothing matches", () => {
    const result = assignLabels(["LICENSE", "Makefile"], config);
    expect(result.labels).toEqual([]);
    expect(result.byFile).toEqual({ LICENSE: [], Makefile: [] });
  });

  describe("conflict resolution via mutually-exclusive groups", () => {
    // A file that is both 'critical' and 'normal' size should only get the
    // higher-priority label because they share an exclusive group.
    const sized: LabelerConfig = {
      rules: [
        { label: "size/large", patterns: ["**"], group: "size", priority: 1 },
        { label: "size/api", patterns: ["src/api/**"], group: "size", priority: 100 },
      ],
    };

    test("only the highest-priority rule in a group wins for a given file", () => {
      const result = assignLabels(["src/api/users.ts"], sized);
      // Both match, but they share group 'size'; api priority(100) beats large(1).
      expect(result.labels).toEqual(["size/api"]);
      expect(result.byFile["src/api/users.ts"]).toEqual(["size/api"]);
    });

    test("the fallback group label still applies to non-conflicting files", () => {
      const result = assignLabels(["README.md"], sized);
      expect(result.labels).toEqual(["size/large"]);
    });

    test("group conflicts are resolved per-file, not globally", () => {
      const result = assignLabels(["src/api/users.ts", "README.md"], sized);
      // api wins for the api file; large wins for the readme. Both appear.
      expect(result.labels).toEqual(["size/api", "size/large"]);
    });
  });
});

// Core logic for the PR label assigner.
//
// Approach: a PR is represented as a flat list of changed file paths. A config
// declares a set of rules, each mapping one label to one or more glob patterns.
// We match every file against every rule, collect the resulting labels, resolve
// conflicts between mutually-exclusive rules by priority, then emit the final
// ordered label set.
//
// Globbing is delegated to Bun's built-in `Bun.Glob` (no third-party deps), so
// the semantics are standard: `*` matches within a path segment, `**` matches
// across segments. See `matchPattern` for the one ergonomic addition.

import { Glob } from "bun";

/** A single label-assignment rule. */
export interface LabelRule {
  /** The label applied to a PR when any of `patterns` match a changed file. */
  label: string;
  /** Glob patterns that select files for this label. */
  patterns: string[];
  /**
   * Conflict-resolution weight. Higher wins. Used for two things:
   *  - ordering the final label set (descending), and
   *  - picking a single winner among rules that share a `group`.
   * Defaults to 0.
   */
  priority?: number;
  /**
   * Optional mutual-exclusion group name. When several rules in the same group
   * match the *same file*, only the highest-priority rule contributes its label
   * for that file (ties broken by declaration order). Rules without a group are
   * always additive — that is how a file gets "multiple labels".
   */
  group?: string;
}

/** Top-level configuration: just an ordered list of rules. */
export interface LabelerConfig {
  rules: LabelRule[];
}

/** Result of assigning labels to a set of changed files. */
export interface LabelResult {
  /** The final, de-duplicated label set, ordered by priority then name. */
  labels: string[];
  /** Per-file breakdown: which labels each changed file contributed. */
  byFile: Record<string, string[]>;
}

/**
 * Match a single glob `pattern` against a single `path`.
 *
 * Standard glob semantics via `Bun.Glob`, with one ergonomic rule: a pattern
 * that contains no `/` is treated as a *basename* matcher and is also tested
 * against the file's basename. This makes intuitive rules like `*.test.*` or
 * `*.md` match files anywhere in the tree (e.g. `src/components/foo.test.tsx`),
 * which is what users expect from a labeler. Patterns that contain a `/` are
 * anchored to the full path with no basename fallback.
 *
 * @throws if `pattern` is empty/whitespace — an empty glob is always a config bug.
 */
export function matchPattern(pattern: string, path: string): boolean {
  if (typeof pattern !== "string" || pattern.trim() === "") {
    throw new Error(`Invalid glob pattern: patterns must be non-empty strings, got ${JSON.stringify(pattern)}`);
  }

  let glob: Glob;
  try {
    glob = new Glob(pattern);
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    throw new Error(`Invalid glob pattern ${JSON.stringify(pattern)}: ${message}`);
  }

  if (glob.match(path)) {
    return true;
  }

  // Basename fallback for slash-free patterns (e.g. `*.test.*`).
  if (!pattern.includes("/")) {
    const basename = path.split("/").pop() ?? path;
    if (basename !== path && glob.match(basename)) {
      return true;
    }
  }

  return false;
}

/** True if any of `rule`'s patterns match `path`. */
function ruleMatchesFile(rule: LabelRule, path: string): boolean {
  return rule.patterns.some((pattern) => matchPattern(pattern, path));
}

/** Effective priority of a rule (default 0). */
function priorityOf(rule: LabelRule): number {
  return rule.priority ?? 0;
}

/**
 * Assign labels to a PR given its `files` (changed paths) and a `config`.
 *
 * Algorithm:
 *  1. For each file, find every rule that matches it.
 *  2. Resolve per-file group conflicts: within each mutual-exclusion `group`,
 *     keep only the single highest-priority matching rule (ties → earliest in
 *     config). Rules without a group are always kept (this is how a file ends
 *     up with multiple labels).
 *  3. Record each file's labels (ordered by priority desc, then name) in
 *     `byFile`, and union all labels into the final set.
 *  4. Order the final set by the maximum priority seen for each label
 *     (descending), then alphabetically for stable, predictable output.
 */
export function assignLabels(files: string[], config: LabelerConfig): LabelResult {
  if (!Array.isArray(files)) {
    throw new Error("assignLabels: `files` must be an array of path strings");
  }

  const byFile: Record<string, string[]> = {};
  // Track the best (max) priority observed for each emitted label, for ordering.
  const labelPriority = new Map<string, number>();

  for (const file of files) {
    // Index matching rules by their original position so ties are deterministic.
    const matches = config.rules
      .map((rule, index) => ({ rule, index }))
      .filter(({ rule }) => ruleMatchesFile(rule, file));

    // Step 2: per-file group conflict resolution.
    const groupWinners = new Map<string, { rule: LabelRule; index: number }>();
    const kept: { rule: LabelRule; index: number }[] = [];
    for (const match of matches) {
      const group = match.rule.group;
      if (group === undefined) {
        kept.push(match); // ungrouped rules are always additive
        continue;
      }
      const current = groupWinners.get(group);
      if (
        current === undefined ||
        priorityOf(match.rule) > priorityOf(current.rule) ||
        // tie → keep the earliest-declared rule
        (priorityOf(match.rule) === priorityOf(current.rule) && match.index < current.index)
      ) {
        groupWinners.set(group, match);
      }
    }
    kept.push(...groupWinners.values());

    // Step 3: order this file's labels and record them.
    const fileLabels = kept
      .slice()
      .sort((a, b) => comparePriorityThenName(a.rule, b.rule))
      .map((m) => m.rule.label);
    byFile[file] = dedupe(fileLabels);

    for (const match of kept) {
      const prev = labelPriority.get(match.rule.label);
      const prio = priorityOf(match.rule);
      if (prev === undefined || prio > prev) {
        labelPriority.set(match.rule.label, prio);
      }
    }
  }

  // Step 4: order the final, unioned label set.
  const labels = [...labelPriority.keys()].sort((a, b) => {
    const pa = labelPriority.get(a)!;
    const pb = labelPriority.get(b)!;
    if (pa !== pb) return pb - pa; // higher priority first
    return a < b ? -1 : a > b ? 1 : 0; // then alphabetical
  });

  return { labels, byFile };
}

/** Sort comparator: higher priority first, then label name ascending. */
function comparePriorityThenName(a: LabelRule, b: LabelRule): number {
  const pa = priorityOf(a);
  const pb = priorityOf(b);
  if (pa !== pb) return pb - pa;
  return a.label < b.label ? -1 : a.label > b.label ? 1 : 0;
}

/** Stable de-duplication preserving first-seen order. */
function dedupe(values: string[]): string[] {
  const seen = new Set<string>();
  const out: string[] = [];
  for (const value of values) {
    if (!seen.has(value)) {
      seen.add(value);
      out.push(value);
    }
  }
  return out;
}

